{
  "sql": "SELECT COALESCE(t.product_category_name_english, 'sin_categoria') AS categoria, ROUND(SUM(oi.freight_value) * 100.0 / SUM(oi.price), 2) AS porcentaje_flete FROM vw_ingresos_por_categoria i LEFT JOIN product_category_translation t ON t.product_category_name = i.categoria_ingles WHERE i.ingresos >= 5000 GROUP BY categoria ORDER BY porcentaje_flete DESC LIMIT 3"
}
